package br.com.tapeteskalke.exception;
import jakarta.servlet.http.HttpServletRequest; import jakarta.validation.ConstraintViolationException; import java.time.*; import java.util.stream.Collectors; import org.slf4j.Logger; import org.slf4j.LoggerFactory; import org.springframework.dao.DataIntegrityViolationException; import org.springframework.dao.OptimisticLockingFailureException; import org.springframework.dao.PessimisticLockingFailureException; import org.springframework.http.HttpStatus; import org.springframework.http.ResponseEntity; import org.springframework.http.converter.HttpMessageNotReadableException; import org.springframework.web.HttpRequestMethodNotSupportedException; import org.springframework.web.bind.MethodArgumentNotValidException; import org.springframework.web.bind.MissingRequestHeaderException; import org.springframework.web.bind.MissingServletRequestParameterException; import org.springframework.web.bind.annotation.*; import org.springframework.web.method.annotation.MethodArgumentTypeMismatchException; import org.springframework.web.servlet.resource.NoResourceFoundException;
@RestControllerAdvice public class GlobalExceptionHandler { private static final Logger log=LoggerFactory.getLogger(GlobalExceptionHandler.class);
 private ResponseEntity<ErrorResponse> error(HttpStatus status,String message,String code,HttpServletRequest r){return ResponseEntity.status(status).body(new ErrorResponse(false,null,message,code,OffsetDateTime.now(ZoneId.of("America/Sao_Paulo")).toString(),r.getRequestURI()));}
 @ExceptionHandler(BusinessException.class) ResponseEntity<ErrorResponse> business(BusinessException e,HttpServletRequest r){return error(e.status(),e.getMessage(),e.code(),r);}
 @ExceptionHandler(MethodArgumentNotValidException.class) ResponseEntity<ErrorResponse> validation(MethodArgumentNotValidException e,HttpServletRequest r){var fields=e.getBindingResult().getFieldErrors().stream().map(f->f.getField()+": "+f.getDefaultMessage()).collect(Collectors.joining("; "));return error(HttpStatus.UNPROCESSABLE_ENTITY,fields.isBlank()?"Dados inválidos":"Dados inválidos — "+fields,"VALIDACAO",r);}
 @ExceptionHandler(ConstraintViolationException.class) ResponseEntity<ErrorResponse> constraint(ConstraintViolationException e,HttpServletRequest r){return error(HttpStatus.UNPROCESSABLE_ENTITY,"Dados inválidos","VALIDACAO",r);}
 @ExceptionHandler(HttpMessageNotReadableException.class) ResponseEntity<ErrorResponse> unreadable(HttpMessageNotReadableException e,HttpServletRequest r){return error(HttpStatus.BAD_REQUEST,"Corpo da requisição inválido","JSON_INVALIDO",r);}
 @ExceptionHandler({MissingRequestHeaderException.class,MissingServletRequestParameterException.class,MethodArgumentTypeMismatchException.class}) ResponseEntity<ErrorResponse> badRequest(Exception e,HttpServletRequest r){return error(HttpStatus.BAD_REQUEST,e instanceof MissingRequestHeaderException h?"Cabeçalho obrigatório ausente: "+h.getHeaderName():"Parâmetro inválido ou ausente","REQUISICAO_INVALIDA",r);}
 @ExceptionHandler(HttpRequestMethodNotSupportedException.class) ResponseEntity<ErrorResponse> method(HttpRequestMethodNotSupportedException e,HttpServletRequest r){return error(HttpStatus.METHOD_NOT_ALLOWED,"Método não suportado","METODO_NAO_SUPORTADO",r);}
 @ExceptionHandler(NoResourceFoundException.class) ResponseEntity<ErrorResponse> notFound(NoResourceFoundException e,HttpServletRequest r){return error(HttpStatus.NOT_FOUND,"Recurso não encontrado","NAO_ENCONTRADO",r);}
 @ExceptionHandler({OptimisticLockingFailureException.class,PessimisticLockingFailureException.class}) ResponseEntity<ErrorResponse> concurrency(Exception e,HttpServletRequest r){log.warn("Conflito de concorrência em {}: {}",r.getRequestURI(),e.getMessage());return error(HttpStatus.CONFLICT,"O registro foi alterado por outra operação. Recarregue e tente novamente","CONFLITO_CONCORRENCIA",r);}
 @ExceptionHandler(DataIntegrityViolationException.class) ResponseEntity<ErrorResponse> integrity(DataIntegrityViolationException e,HttpServletRequest r){log.warn("Violação de integridade em {}: {}",r.getRequestURI(),e.getMostSpecificCause().getMessage());return error(HttpStatus.CONFLICT,"Operação viola uma regra de integridade dos dados (registro duplicado ou valor inválido)","INTEGRIDADE",r);}
 @ExceptionHandler(Exception.class) ResponseEntity<ErrorResponse> unknown(Exception e,HttpServletRequest r){log.error("Erro inesperado em {} {}",r.getMethod(),r.getRequestURI(),e);return error(HttpStatus.INTERNAL_SERVER_ERROR,"Erro interno inesperado","ERRO_INTERNO",r);}
}
